--- AVTP common header prefix (IEEE 1722-2025 4.4.3)
function M.add_common(tree, tvb, off)
    tree:add(M.f.avtp_subtype, tvb(off + 0, 1))
    tree:add(M.f.avtp_sv, tvb(off + 1, 1))
    tree:add(M.f.avtp_version, tvb(off + 1, 1))
    tree:add(M.f.avtp_stream_id, tvb(off + 4, 8))
end

--- AVTP stream data header, version 0 (IEEE 1722-2025 4.4.4.1)
function M.add_stream_v0(tree, tvb, off)
    tree:add(M.f.avtp_subtype, tvb(off + 0, 1))
    tree:add(M.f.avtp_sv, tvb(off + 1, 1))
    tree:add(M.f.avtp_version, tvb(off + 1, 1))
    tree:add(M.f.avtp_mr, tvb(off + 1, 1))
    tree:add(M.f.avtp_r, tvb(off + 1, 1))
    tree:add(M.f.avtp_fsd1, tvb(off + 1, 1))
    tree:add(M.f.avtp_tv, tvb(off + 1, 1))
    tree:add(M.f.avtp_sequence_num, tvb(off + 2, 1))
    tree:add(M.f.avtp_fsd2, tvb(off + 3, 1))
    tree:add(M.f.avtp_tu, tvb(off + 3, 1))
    tree:add(M.f.avtp_stream_id, tvb(off + 4, 8))
    tree:add(M.f.avtp_avtp_timestamp, tvb(off + 12, 4))
end

--- AVTP stream data header, version 1 (IEEE 1722-2025 4.7.4)
function M.add_stream_v1(tree, tvb, off)
    tree:add(M.f.avtp_subtype, tvb(off + 0, 1))
    tree:add(M.f.avtp_sv, tvb(off + 1, 1))
    tree:add(M.f.avtp_version, tvb(off + 1, 1))
    tree:add(M.f.avtp_mr, tvb(off + 1, 1))
    tree:add(M.f.avtp_r, tvb(off + 1, 1))
    tree:add(M.f.avtp_fsd1, tvb(off + 1, 1))
    tree:add(M.f.avtp_tv, tvb(off + 1, 1))
    tree:add(M.f.avtp_format_specific_data_0, tvb(off + 2, 1))
    tree:add(M.f.avtp_fsd2, tvb(off + 3, 1))
    tree:add(M.f.avtp_tu, tvb(off + 3, 1))
    tree:add(M.f.avtp_stream_id, tvb(off + 4, 8))
